import React from 'react';

export type RequestReturnLinkProps = { savedViewQuery: string };

export function RequestReturnLink({ savedViewQuery }: RequestReturnLinkProps) {
  const query = savedViewQuery.startsWith('?') ? savedViewQuery : `?${savedViewQuery}`;
  const target = savedViewQuery ? `/requests${query}` : '/requests';
  return <a href={target}>Back to requests</a>;
}

// The detail page passes the query captured when the request was opened.
// Review is still needed for keyboard focus on return and an empty result list.
